45: /** Pure projection of a validated A2UI surface onto UAR-owned React controls. */
46: export function A2uiSurfaceRenderer({
47:   components,
48:   data,
49:   onDataChange,
50:   onAction,
51:   actionPending = false,
52:   statusMessage,
53:   idPrefix = "",
54: }: A2uiSurfaceRendererProps) {
55:   const componentMap = new Map(components.map((component) => [component.id, component]));
56:   const root = componentMap.get("root") ?? components[0];
57: 
58:   const renderComponent = (componentId: string, ancestors: Set<string>): ReactNode => {
59:     if (ancestors.has(componentId)) {
60:       return <p className="text-sm text-destructive">A2UI component cycle detected at {componentId}.</p>;
61:     }
62:     const component = componentMap.get(componentId);
63:     if (!component) {
64:       return <p className="text-sm text-destructive">A2UI component {componentId} is unavailable.</p>;
65:     }
66:     const nextAncestors = new Set(ancestors).add(componentId);
67: 
68:     switch (component.component) {
69:       case "Text": {
70:         const text = String(dynamicValue(component.text, data) ?? "");
71:         if (component.variant === "h1") return <h2 className="text-lg font-semibold text-foreground">{text}</h2>;
72:         if (component.variant === "h2" || component.variant === "h3") {
73:           return <h3 className="text-base font-semibold text-foreground">{text}</h3>;
74:         }
75:         return <p className={cn("text-sm text-foreground", component.variant === "caption" && "text-xs text-muted-foreground")}>{text}</p>;
76:       }
77:       case "Button":
78:         {
79:           const child = componentMap.get(component.child);
80:           const label = child?.component === "Text"
81:             ? String(dynamicValue(child.text, data) ?? "")
82:             : renderComponent(component.child, nextAncestors);
83:         return (
84:           <Button
85:             type="button"
86:             size="sm"
87:             variant={component.variant === "borderless" ? "ghost" : component.variant === "secondary" ? "outline" : "default"}
88:             disabled={actionPending}
89:             onClick={() => onAction(component.action.event.name, component.action.event.context ?? {})}
90:           >
176:       case "Row":
177:         return <div className="flex flex-wrap items-center gap-2">{component.children.map((id) => <Fragment key={id}>{renderComponent(id, nextAncestors)}</Fragment>)}</div>;
178:       case "Column":
179:         return <div className="flex flex-col gap-3">{component.children.map((id) => <Fragment key={id}>{renderComponent(id, nextAncestors)}</Fragment>)}</div>;
180:       case "Card":
181:         return <div className="rounded-xl bg-card p-4">{renderComponent(component.child, nextAncestors)}</div>;
182:       case "Divider":
183:         return <Separator orientation={component.axis === "vertical" ? "vertical" : "horizontal"} />;
184:     }
